      SUBROUTINE BGET(II)CC     GET PARAMETERS DESCRIBING THE LENGTH AND CENTRAL FIELD OF C     A BENDING MAGNETCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15A.CIN'       INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'XRAN.CIN'CC     LOCAL VARIABLESC      INTEGER  IL, IB, IRHO, IANG, IADR, II, IN, IK1, IRMPS      REAL  DATAR, RHO      EXTERNAL DATARCC---------------------------------------------------------------C     STORAGE POSITION OF PARAMETERSC      NL = 1      NBV = 2      NRHO = 3      NANG = 4      NN = 5      NK1 = 6      NRMPS = 7      NRNMS = 8      NVR = 9      NNP = 10      NK1P = 11      NBDB = 12      NK2 = 13      NBDBP = 14      NK2P = 15      NGAM = 16      NK3 = 17      NTILT = 18      IF (IPTOJ(NL) .EQ. 1 .AND. IPTOJ(NBV) .EQ. 2 .AND. ANIN) THEN        IPTOJ(NBV) = 0        IPTOJ(NANG) = 2      ENDIF      IL = IPTOJ(NL)      IB = IPTOJ(NBV)      IRHO = IPTOJ(NRHO)      IANG = IPTOJ(NANG)CC     MAGNET LENGTH GIVENC      IF (IL .EQ. 0) GO TO 50      IADR = II + IL      LBEND = DATAR(IADR)      IF (PRAN4(1) .NE. 0.0) LBEND = LBEND + PRAN4(1)*XRAN(1)      LBEND = LBEND*UNITI(8)CC     LENGTH AND MAGNETIC FIELD GIVENC      IF (IB .EQ. 0) GO TO 10      IADR = II + IB      B = DATAR(IADR)      IF (PRAN4(2) .NE. 0.0) B = B + PRAN4(2)*XRAN(2)      B = B*UNITI(9)*RI/PREF      H0 = B/RI      AL = H0*LBEND      RHO = 0.0      IF (H0 .NE. 0.0) RHO = 1.0/H0      GO TO 100CC     LENGTH AND BENDING RADIUS GIVENC   10 IF (IRHO .EQ. 0) GO TO 20      IADR = II + IRHO      RHO = DATAR(IADR)      IF (PRAN4(3) .NE. 0.0) RHO = RHO + PRAN4(3)*XRAN(3)      RHO = RHO*UNITI(8)      H0 = 1.0/RHO      AL = H0*LBEND      IF (RI .NE. 0.0) B = H0*RI      GO TO 100CC     LENGTH AND BENDING ANGLE GIVENC   20 IADR = II + IANG      AL = DATAR(IADR)      IF (PRAN4(4) .NE. 0.0) AL = AL + PRAN4(4)*XRAN(4)      AL = AL*UNITI(7)      H0 = AL/LBEND      B = RI*H0      GO TO 100CC     FIELD AND BENDING ANGLE GIVENC   50 IF (IB .EQ. 0) GO TO 70      IADR = II + IB      B = DATAR(IADR)      IF (PRAN4(2) .NE. 0.0) B = B + PRAN4(2)*XRAN(2)      B = B*UNITI(9)*RI/PREF      IADR = II + IANG      AL = DATAR(IADR)      IF (PRAN4(4) .NE. 0.0) AL = AL + PRAN4(4)*XRAN(4)      AL = AL*UNITI(7)      H0 = B/RI      IF (H0 .NE. 0.0) THEN        RHO = 1.0/H0        LBEND = RHO*AL      ENDIF      GO TO 100CC     BENDING RADIUS AND ANGLE GIVENC   70 IADR = II + IRHO      RHO = DATAR(IADR)      IF (PRAN4(3) .NE. 0.0) RHO = RHO + PRAN4(3)*XRAN(3)      RHO = RHO*UNITI(8)      IADR = II + IANG      AL = DATAR(IADR)      IF (PRAN4(4) .NE. 0.0) AL = AL + PRAN4(4)*XRAN(4)      AL = AL*UNITI(7)      LBEND = RHO*AL      IF (RI .NE. 0.0) B = RI/RHO      H0 = 1.0/RHOCC     SPECIFICATION OF NORMALIZED FIELD GRADIENTC  100 IN = IPTOJ(NN)      IK1 = IPTOJ(NK1)      IF (IK1 .EQ. 0 .AND. PRAN4(6) .EQ. 0.0) THEN        IF (IN .EQ. 0) THEN          NB = 0.0        ELSE          IADR = II + IN          NB = DATAR(IADR)        ENDIF        IF (PRAN4(5) .NE. 0.0) NB = NB + PRAN4(5)*XRAN(5)      ELSE        IF (IK1 .EQ. 0) THEN          K1 = 0.0        ELSE          IADR = II + IK1          K1 = DATAR(IADR)        ENDIF        IF (PRAN4(6) .NE. 0.0) K1 = K1 + PRAN4(6)*XRAN(6)        K1 = K1/UNITI(8)**2        IF (H0 .NE. 0.0) NB = - K1/H0**2      ENDIFCC     FRACTIONAL MISTUNING FOR HORIZONTAL STEERINGC      IRMPS = IPTOJ(NRMPS)      IF (IRMPS .NE. 0) THEN        IADR = II + IRMPS        RMPS = DATAR(IADR)      ELSE        RMPS = RMPSI      ENDIF      IF (PRAN4(NRMPS) .NE. 0.0)     1    RMPS = RMPS + PRAN4(NRMPS)*XRAN(NRMPS)      RETURN      END